ier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r121_planned_get_replay_1c7b37e_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r122_get_done_control_52ef745_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r123_get_done_stage_trace_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r124_master_rpc_fastpath_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r125_master_control8_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r126_global_control8_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r128_remote_put_admission16g4096_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r129_remote_put_admission24g6144_e7fffd0_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r130_remote_put_batch_e02590b_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r131_tier1_wait_memholder_97ab9f2_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r132_content_depths_compat_0216a00_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r133_device_headroom_ad8475e_20260806|tier1_independent_005_netobs_enddepth288_fast25_mlp_p14_r134_post_read_drop_r132_ad8475e_20260807|tier1_independent_005_netobs_enddepth288_r112_post_read_retain|tier1_independent_005_netobs_enddepth288_r112_post_read_drop|tier1_independent_005_netobs_r112_eager_all_post_read_retain|tier1_independent_005_netobs_r112_eager_all_post_read_drop|tier1_independent_005_netobs_enddepth288_r92_gdr_off_parallel_backing) ;;
  tier1_independent_005_netobs_enddepth288_r106_regression_r103_adapter) ;;
  tier1_independent_005_netobs_enddepth288_r107_regression_r103_adapter) ;;
  tier1_independent_005_netobs_enddepth288_r108_regression_r103_adapter) ;;
  tier1_independent_005_netobs_enddepth288_r109_regression_r103_adapter) ;;
  tier1_independent_005_netobs_enddepth288_p13_generic_pressure_r103_adapter) ;;
  tier1_independent_005_netobs_enddepth288_p14_burst_reserve_r103_adapter) ;;
  *)
    echo "guarded launcher refuses variant: $variant" >&2
    exit 2
    ;;
esac

selected_gpu_ids="${E44_GPU_SELECTED_IDS:-0,1}"
if [[ ! "$selected_gpu_ids" =~ ^[0-9]+,[0-9]+$ ]]; then
  echo "E44_GPU_SELECTED_IDS must contain exactly two GPU indices" >&2
  exit 2
fi

interfering="$(
  pgrep -af '[i]nference_like_compute.py|[.]gpu_burn_script_|bash /storage/zgf/[g]pu_burner.sh watchdog$' || true
)"
if [ -n "$interfering" ]; then
  echo "r38 GPU preflight found burner/watchdog/inference:" >&2
  printf '%s\n' "$interfering" >&2
  exit 1
fi

compute="$(nvidia-smi -i "$selected_gpu_ids" --query-compute-apps=pid,process_name,used_memory --format=csv,noheader,nounits 2>/dev/null || true)"
if [ -n "$compute" ]; then
  echo "r38 GPU preflight found compute processes:" >&2
  printf '%s\n' "$compute" >&2
  exit 1
fi

gpu_idle_memory_tolerance_mib="${E44_GPU_IDLE_MEMORY_TOLERANCE_MIB:-0}"
case "$gpu_idle_memory_tolerance_mib" in
  0 | 4) ;;
  *) echo "E44_GPU_IDLE_MEMORY_TOLERANCE_MIB must be 0 or the explicitly authorized 4 MiB driver residual" >&2; exit 2 ;;
esac
gpu_state="$(nvidia-smi -i "$selected_gpu_ids" --query-gpu=index,memory.used,utilization.gpu --format=csv,noheader,nounits)"
bad_state="$(printf '%s\n' "$gpu_state" | awk -F, -v tolerance="$gpu_idle_memory_tolerance_mib" '($2 + 0 > tolerance || $3 + 0 != 0)')"
if [ -n "$bad_state" ]; then
  echo "r38 GPU preflight requires selected GPUs $selected_gpu_ids at <=${gpu_idle_memory_tolerance_mib} MiB/0%:" >&2
  printf '%s\n' "$gpu_state" >&2
  exit 1
fi

if [ "${E44_R38_GPU_PREFLIGHT_ONLY:-0}" = 1 ]; then
  echo "r38 GPU preflight passed: node=$node"
  exit 0
fi

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
exec bash "$script_dir/launch_gpu_e44_r28_netobs.sh" "$root" "$node" "$variant"
